def _is_loopback_address(host):
    return (
        host.startswith("127.")
        or host.startswith("::ffff:127.")
        or host == "::1"
    )

def _convert_text_list_to_dbus_format(text_list):
    array = dbus.Array(signature="ay")
    for text in text_list:
        array.append([dbus.Byte(ord(c)) for c in text])
    return array

