        raise exceptions.ValidationError(msg.format(arg=arg))
    elif urllib.parse.urlparse(arg).scheme == "":
        raise exceptions.ValidationError(msg.format(arg=arg))

def check_uris(arg, msg="Expected a list of URIs, not {arg!r}"):
